S='SPEC_METHOD'
SG=['TRANSFORMATION_LIBRARY.contract-application','FOUNDATIONS.result-algebra','FOUNDATIONS.result-conjunction']
add(S,'spec-driven-homeostatic-methodology','consumer_binding','Applying Spec Method constitutional contracts in their declared domain.',
    'Spec contracts consume foundational premises through contract application, bounded construction and workspace-derived context; UP-020 keeps construction, assessment and disposition predicates/authority separate.',
    ['Retain ODD graph meaning and Design module realization at their respective owners.', 'Treat lifecycle/change-class/triage labels as inputs, not verdicts; preserve unsupported input, legal performance, diagnostic precedence, absent coverage and effects.'],
    ['Bind/Acquire/Transform/Evaluate/Conjoin/Dispose may compose without six mandatory stages or a runtime API.'], ['Actual chosen contract, subject, policy and grants.'], SG+['FOUNDATIONS.bounded-construction'],
    policy=['Directional Goals chain, grants and domain dispositions are method choices; foundations/helpers supply no permission.'])
add(S,'canonical-compression','non_deciding_locator','Navigating the deciding clauses of Spec Method.',
    'Derived synopsis of constitutional direction, WHAT/HOW separation, Product overlay, semantic resolution, ambiguity/lifecycle, evidence, trace/repricing and sprint boundaries; it supplies no independently owned replacement law.',
    ['Resolve the deciding owning clauses for material use.'], [], [], ['SPEC_METHOD.constitutional-chain','SPEC_METHOD.bounded-context-semantic-resolution','SPEC_METHOD.ambiguity-governance-rule'])
add(S,'position','constraint','Spec-driven software, human or mixed-process work.',
    'Declared authority makes work re-derivable, auditable and correctable; realizations satisfy declared obligations through their bound tenants, and any imperative procedure is subordinate to that authority.',
    [], ['Declarative truths/structures/interfaces/constraints/evidence are the preferred form; internal procedure remains permitted.'], ['Declared authority and realization relationship.'])
add(S,'stdo-method-identity','definition_data','Interpreting STDO in urn:stdo:bounded-context:method-identity under the selected complete basis.',
    {'S':'Specification: SPEC_METHOD','T':'Ticketing: TICKET_METHOD','D':'Design: DESIGN_MODULE_METHOD','O':'complete Outcome-Driven Development pillar: ODD_METHOD'},
    ['Do not infer independent member selection or a four-member Product; authority is one complete immutable cut/inventory.', 'ODD identity and graph-native meaning remain at ODD_METHOD.'], [], ['Selected complete release identity.'])
add(S,'probabilistic-work-boundary','constraint','Probabilistic, agentic or delegated work; graph refinements generally bind an edge/vector traversal.',
    'Declare I/O, context, capability/role, evidence/evaluator, provenance and lawful control-state boundary; worker owns internal HOW unless Product explicitly promotes part to reusable structure.',
    ['Before use map each control state plus reason to actual task predicate; hidden unconstrained reasoning must return through declared contracts/evidence/provenance/control truth.', 'Deterministic checks may prove/optimize local paths but cannot make domain strategy constitutional; framework prescription beyond contract crosses authority.'],
    ['Product may explicitly promote selected HOW; unconstrained internal strategy otherwise remains worker-owned.'], ['Work contract, actual returned state/reason, evidence/performance/effects and any Product promotion.'], ['FOUNDATIONS.result-algebra'],
    'Completion label needs established completion; defeated task falsified, undecided task indeterminate unless scope/basis diagnosis applies. Retain missing reason/non-performance/unknown effects. Lawfulness of stop/continue is a separate decision.')
add(S,'recursive-product-taxonomy','definition_data','Recursive Product roles in urn:stdo:bounded-context:recursive-product-taxonomy.',
    {'Substrate':'lower Product/runtime used to build others','Development Product':'one exact Install acting as builder substrate for a Source Project; no new identity or authority transfer','Source Project':'mutable workspace authoring next cut','Release Cut':'immutable annotated published RC boundary','Product':'immutable thing when cut accepted','Install':'stamped workspace instance of released Product','Artifact':'published output from source project or configured Install','Product Definition':'present-tense source WHAT, conventionally PRODUCT.md, not released artifact'},
    ['Keep mutable source, cut, Product, Install, builder role and definition distinct; bind exact builder Install.'],
    ['Products may depend on Products; Installs may build successors of themselves, other Products or artifacts.'], ['Exact release/install/source roles and identities.'])
add(S,'manifesto','constraint','Claiming work is spec-driven.',
    'Current Goals govern Intent, Intent Product, Product full constitutional requirements, requirements structural design and requirements+design realization; evidence and gap analysis drive cumulative repricing while authority remains directional.',
    ['Define current goals before deeper repricing, Intent before implementation and present-tense Product before requirements.', 'Reduce major-boundary ambiguity; ground realization/evidence, reprice constitutional gaps.', 'Keep live surface current; remove transitional paths unless explicitly retained compatibility; derived indexes/views/reports are read models.'],
    ['Prefer declarations over imperative procedure.'], ['Current authoritative chain, realization trace, evidence, gap/repricing and compatibility decisions.'], ['SPEC_METHOD.constitutional-chain'])
add(S,'spec-drivenness-litmus','constraint','Assessing a claim of spec-driven development.',
    'Each chain layer is derivable from its governors; each live requirement has status/category/design owner and realization or explicit deferral; code behavior has authority; capability has operational evidence; drift and major ambiguity receive governed treatment.',
    ['No silent in-place rewriting of live constitutional domain artifacts.', 'Every material Product/module/function/application/runtime/capability has lifecycle signal or recorded release/deploy/live-use/telemetry/retirement gaps.'], [], ['Layer derivability, trace/deferments, authority, operational proof, history, ambiguity and lifecycle gaps.'])
add(S,'process-constitution','constraint','Bootstrapping or reconstructing project process from methodology and domain specification.',
    'Method governs layer relations/sufficiency/classification/authority; bound WHAT owns constitution while design/tenants/code/overlay/views realize or route it without becoming co-equal law.',
    ['Requirements derive from Product and may be family-grouped; overlay locates actual authorities without owning content.', 'Method alone can bootstrap process; reconstructing the project additionally requires surviving domain specification.'],
    ['Conventional filenames/folders are defaults; existing URI layouts need not move/duplicate.', 'Shared and tenant-local designs select mechanism.'], ['Bound WHAT/HOW and surviving domain specification.'])
add(S,'stdo-product-definition-overlay-and-layout-independence','constraint','Declaring a current distinct Product WHAT or discovering its definition.',
    'One stdo_<label>.json describes each distinct current WHAT; multiple tenants of one WHAT share that definition. Definition Label is a directory-local discovery label; product.definition_id is a workspace-unique stable continuing mutable-WHAT identity, separate from release/Product identity.',
    ['Label uses stable lowercase ASCII letters/digits/hyphens/underscores; fork/replacement/independently governed WHAT gets another definition_id.', 'Identity URIs remain owner-governed; strings/paths/labels confer no authority.', 'Resolve relative URIs against definition retrieval URI; source_project may be elsewhere; proximity supplies no authority.', 'Use product-definition schema/template as accepted interoperability shape for identity/location/relation/discovery, not second semantic owner.'],
    ['Multiple definitions may share a directory for distinct WHATs; stdo_default.json is default single-definition name.', 'Continuing definition identity may span releases.'], ['Actual Product authority, definition set, source/retrieval coordinates and tenant relationships.'], ['IDENTITY_METHOD.authority-identity-and-conservation-stdo-up-004'])
add(S,'required-definition-relations','definition_data','A Product Definition Overlay.',
    {'relations':['product identity/name/source/bounded_context or null','constitution.stdo source/selector/exact basis+digest','additional_authorities','basis-qualified entrypoints','agent_bootstrap','local_constitution axioms/overrides/disambiguations with authority/target/basis/scope','accepted reference_frame_bases with authorities/scopes','what Intent/Product/specification','how shared surfaces and >=1 independent tenant','ticketing Goals/tickets/comments/optional sprints','explicit composition','$schema','kind=stdo.product-definition']},
    ['Overlay owns routes/relations only; duplicating referenced truth creates rival authority.', 'product.bounded_context encloses WHAT or is null; it is not exhaustive registry nor flattening of subordinate/peer/tenant/runtime contexts.', 'Local disambiguation names exact context.'], [], ['Product bindings and owning content/context declarations.'])
add(S,'constitutional-set-sufficiency','constraint','Selecting a Product\'s complete governing constitutional set.',
    'The complete selected sources make axioms/invariants/refusals, ontology/identity/lifecycle, epistemology/evidence/uncertainty/authority, taxonomy and semantics recoverable for governed scope.',
    ['STDO basis is one complete immutable cut/exact manifest, not selected subset; list every additional constitutional source.', 'Each entrypoint resolves against its named basis and cannot narrow/replace the constitution.', 'Product-meaning ontology belongs in/cited by WHAT; Design Ontology derives from it and cannot invent missing Product meaning.'],
    ['Dimensions need no prescribed filenames/folders or one-document partition; multiple dimensions may share/distribute documents.'], ['Complete selected authorities, governed scope and recoverable semantics.'])
add(S,'shared-installed-release-basis-and-toolchain-manager','constraint','Installing, syncing, verifying, resolving, adopting or fleet-managing the selected STDO basis and bootstrap.',
    'Operative STDO selection is immutable release URI plus deterministic installed-manifest SHA256 binding tag/commit/repository-tree/standards-tree/exact inventory/member/auxiliary bytes; registry/source/selector/schema/agent files cannot substitute it.',
    ['Adoption plan binds definition identity/bytes/current basis and exact target cut/tag/commit/tree/manifest; canonical UTF-8 sorted-key two-space JSON uses LF plus final LF, excluding machine-local paths/install status. Fleet order is deterministic discovery-path order.', 'install changes no definition; sync verifies only pinned basis and ignores selector; read-only adopt --dry-run presents plan; mutating adopt needs exact prior accepted digest, rederives before install, rechecks definition and atomically changes only basis/schema; drift refuses.', 'Fleet writes need whole-selection authorization/aggregate digest; nesting does not imply composition.', 'Every manager-store entry from configured root down is physical declared directory/regular file: reject symlinks/junctions/reparse/device/socket/redirection, undeclared entries and unmanifested aliases.', 'Fail closed on missing/moved cuts, tag/commit/digest/member mismatch, ambiguous discovery, stale/unaccepted plan, URI escape or malformed bootstrap; parse stdo: scheme case-insensitively before schema loading and require same exact cut.', 'Bootstrap targets are portable relative source-project paths; reject absolute/traversal/redirection/escape, confine fleet sources to authorized root, preflight all before writes. Replace exactly one correctly ordered marker span; preserve every external byte including whitespace or append with original bytes exact prefix.', 'Recursive discovery prunes .git,.hg,.svn,.bzr,.venv,venv,node_modules,vendor,site-packages,build,dist,out,target,.gradle,.tox,.nox,.cache,.ruff_cache,.mypy_cache,.pytest_cache,__pycache__,.genesis,.stdo; definitions themselves cannot be symlinks. Exclusion does not prove absent independent Products.'],
    ['Store location is machine-local; multiple definitions may select different cuts concurrently and need no local standards copy.', 'status/verify/list/manifest/resolve are read-only for definitions; manifest is integrity evidence, not constitution; possession of a plan hash alone confers no authority.'], ['Actual exact release/manifest, physical store entries, current definition bytes, accepted plan/authority, bootstrap preimages, selected fleet/root and observations.'], SG,
    'Evaluate command-specific exact-input conditions: violated condition falsified; unavailable deciding evidence indeterminate; unusable subject/basis invalid_basis; outside scope/capability out_of_frame; all conditions established satisfied. Fail-closed is withholding dependent operation, not a sixth verdict. Actual adoption/publication/recovery completion and effects remain separate observed predicates.')
add(S,'explicit-complete-consumer-update','constraint','Separately selected cohort-update operation on one Product Definition and owner-selected complete companion/native-route/derived-context population.',
    'A read-only complete plan binds selected release cohort and companion identities/inventories, physical effect destinations and binding preimages, replacement locators/native routes and derived-source observations; mutation needs actual authority, exact accepted digest and unchanged rederivation.',
    ['Invocation evidence does not become persistent dependency registry/lock; Product still owns composition and release owners identity. Caller selects every route/context; empty selection is not proof no semantic context exists.', 'Use adoption canonical JSON hashing; install status changes no plan authority/digest. Existing adopt/sync/fleet retain narrower bounds.', 'Verify dependency closure/companion definitions/releases/members, stage absent immutable installs, verify existing without repair, preflight all targets.', 'Change only selected basis/schema, existing composition locators/contracts and selected native/install links; preserve history/unrelated content; no new local checker, Product meaning change or semantic-map relabeling.', 'Missing/ambiguous/changed/unavailable derived evidence holds before consumer effects; semantic re-entry belongs to source owner and freshness alone proves no conformance.', 'After staging recheck consumer/source preimages; verify every resulting binding/companion before completion. Caught application failure restores affected consumer preimages; exclusive consumer write scope required.', 'No crash-atomic promise across paths: abrupt host/process loss or unavailable rollback needs recovery from presented preimages before complete claim.'],
    ['New staged immutable installs may remain unused after refusal/rollback.'], ['Selected whole population/cohort, exact preimages/destinations, source evidence, exclusive-write authority, accepted plan and actual effects.'], SG,
    'Complete-update predicate requires every selected binding and companion satisfy accepted plan; observed mismatch falsifies, unobserved completion indeterminate. Pre-mutation refusal needs observed not_started. Recovery command is not reversal proof: reverted requires every begun part observed reversed. Separate staged-install and consumer boundaries, retaining partial/unknown effects.')
add(S,'bounded-context-semantic-resolution','constraint','Any material lexical occurrence or cross-context semantic seam.',
    'Resolve (term, bounded-context identity, owning authority, selected basis, governed scope) to exactly one admitted concept by identifying scope/nearest explicit context, authorities/basis, local+imported concepts and authorized overrides/disambiguations, in that order.',
    ['Context requires owner-declared stable identity/owner/basis/scope; headings, glossary/schema values, filenames and URIs alone create none. Defining a concept inside another owner\'s context needs explicit owner relation.', 'Equal/different spelling, location, actor or implementation proves no equality/difference/inheritance/authority; zero or multiple concepts withhold material use, with no familiarity/recency/glossary fallback.', 'Glossary indexes exact declaring/owning clauses only; listed concept applies only through address or explicit import.', 'Cross-context relation names exact concepts/contexts, kind/direction/lawful inverse, preserved/changed meaning/loss/refusals, separate owners, source/target bases/scope/provenance and lifecycle/invalidators.', 'Import preserves meaning; translation changes directionally; equivalence requires authority-established equality (not opposing translations); disambiguation selects without equating.', 'Specialization declares exact target, preserved/narrowed meaning, excluded source instances and inverse absence/law; name alone establishes nothing.'],
    ['An owning surface may declare context for subordinate occurrences; uniquely resolved prose need not repeat qualifiers.'], ['Exact semantic address, complete material candidate set, authorized definitions/imports/overrides and current relation validity.'], SG,
    'Unique admitted meaning satisfies; established complete set with zero/multiple candidates falsifies; incomplete search/unavailable definition is indeterminate, not proved zero. Invalid/contradictory address/basis is invalid_basis; outside evaluator scope/capability out_of_frame. Retain unresolved/ambiguous diagnostic and withhold dependent use.')
add(S,'local-constitutional-binding','constraint','Binding local axioms, overrides or semantic disambiguations in the overlay.',
    'Each local entry cites decision URI, existing lawful owner, affected clause/ambiguity where relevant and exact scope; local category or overlay presence does not grant authority.',
    ['Disambiguation additionally binds exact term/context, complete material candidates, resolves_to member of candidates, every needed basis and uri/authority/applies_to.', 'Resolution URI owns meaning; cross-context candidates require complete authorized import/translation/equivalence carrier, not repeated metadata meaning.', 'Use explicit empty array for no entries; omission is not equivalent.'], [], ['Local decision carrier, actual authority, scope and candidate/basis resolution.'], ['SPEC_METHOD.bounded-context-semantic-resolution'])
add(S,'collective-reference-frame-basis','constraint','Product-bound collective engagement and exact actor activations.',
    'A nonempty accepted reference_frame_bases locator set resolves Product-owned declaration(s) of exact method/optional-profile basis, admitting owners/scopes, frames/evaluation inventory, actor rules/envelopes, semantic/evaluation/operation/decision grants, result/coverage/composition, triggers and invalidation.',
    ['Separate profile availability, Product adoption and exact authorized activation; principles/optional Baseline select none automatically.', 'Execution instruction binds actor to exact frame/configuration/evaluation/subject/basis/evidence/envelope; it does not mutate overlay or appoint permanent frames.', 'Actor/frame identities and overlapping/time-varying activations confer no extra power.', 'Cross-Product outcome requires role map distinguishing source/definition/checkpoint/cut/Product/Install/Artifact/dependent Product, and Development Product role over exact Install; each directed edge binds roles, authority/contracts/lifecycle/evidence/refusal/invalidators.', 'Admit complete actual identities/scope/grants/results in templates; nominal runtime Frame does not enroll without explicit evaluation/authority declaration.'],
    ['Product may adopt optional profile or another configuration; source-linked prose suffices and no schema/a_c/prompt/runtime engine is required.'], ['Accepted concrete frame-basis declaration, actual grants, exact activation and cross-Product relation if used.'])
add(S,'what-how-and-work-carriers','constraint','One shared constitutional Product WHAT realized by one or more independent project-owned tenants.',
    'WHAT supplies admissible states/outcomes/constraints/evidence/permitted changes; each tenant design binds realising operations/invariants, composition, performers, effects, assumptions and observations without changing common meaning.',
    ['At design admission every affected requirement maps to operation/invariant, interface-preservation obligation and defeating evidence.', 'Measure material context/time/memory/communication/human-effort/spend with units and declared boundary; assess attention by actual use, not universal score.', 'A route or structurally valid a_c representation does not prove preservation/fitness or select executor; actor/author identity does not choose operation kind.', 'Intent and Product each have canonical WHAT entry; specification may have multiple surfaces.', 'how.build_tenants is canonical identity/root/design/implementation registry; how.common is explicitly adopted shared realization law, with companion registry only a view.', 'ticketing bindings locate work wave, durable ticket lanes, commentary and optional sprint; they do not transfer state authority.'],
    ['Singleton tenancy is lawful; software/hardware/people/organizations/mixed execution allowed.', 'Calculus may span tools/teams/environments if bindings preserve its laws; language change alone needs no new calculus.', 'Work carriers may be directories/resources/trackers/APIs/queries.'], ['Common requirement set, actual computational/execution binding, preservation/evidence, measured resources and Product carrier/tenant definitions.'], SG)
add(S,'recursive-discovery-and-explicit-composition','constraint','Discovering a selected workspace or resolving a directed Product composition edge.',
    'Recursively discover root/deep stdo_*.json within boundary; composition requires explicit target locator+expected definition identity, authority-owned directed relation and nonempty exact contracts, never nesting.',
    ['Move updates locator while preserving identity; replaced target identity fails closed; exact immutable versions require their own verified relation coordinates.', 'Validate each selected released schema, URI/fragment resolution, unique definition IDs and per-definition tenant IDs, applicable/reconciled frame bases, complete congruent disambiguation and cross-context seams, exact targets/contracts, and no rival Product/tenant/ticket/constitutional authority.', 'Draft-2020-12 shape alone is insufficient: explicitly assert RFC3986 URI syntax, then separately resolve fragments/identity/uniqueness/sufficiency/semantic and authority relations.'],
    ['Directory nesting supplies no inheritance/override; arbitrary permitted layout depth remains supported.'], ['Selected discovery boundary, exact definitions, assertion-capable validation, resolved relations/owners and semantic evidence.'])
add(S,'semantic-resolution-conformance-cases','constraint','Qualifying semantic-resolution behavior under exact selected basis.',
    'Conformance distinguishes unique local resolution, complete authorized cross-context resolution and material collision without guessed meaning.',
    ['Frame evaluation/runtime, Owner specialist/authority, Product released/definition, and Tenant build/customer/runtime meanings remain distinct absent explicit relation; User roles/person/principal/account/actor/operator/data-subject remain unresolved until downstream authority binds them.', 'Cover zero/multiple candidates, selected concept outside set, glossary fallback, incomplete relation, authority/basis mismatch, undeclared loss and invalidation.', 'Correct output reached through guessed meaning does not satisfy conformance.'], [], ['Exact source-defined positive/adverse cases and actual behavior on the selected basis.'], ['SPEC_METHOD.bounded-context-semantic-resolution'])
add(S,'one-constitutional-surface-and-version-boundary-stdo-surface-001','constraint','Publishing/adopting method law or deriving instructions from it.',
    'One owning standard owns each law and other members reference it; operative authority is one complete released STDO cut with exact inventory/digests/review/human acceptance/identity.',
    ['Views/templates/compressions/comments/candidates/installs/source cannot become selectable partial constitution or reinterpret law.', 'Derived instructions preserve conditions, obligations, permissions, exclusions, owners and invalidators; exact hashes do not excuse semantic strengthening/weakening. Accessible exact references or supplied meaning are required.', 'STDO owns normative algebra/authority/abstract transition/admissibility/causal order/evidence; consumers own concrete types/files/tools/runtime/tests unless method explicitly accepts a concrete interoperability form.', 'Adding tool/workflow/runtime/assurance/consumer realization to STDO Product scope requires separate explicit human authorization; recording agents cannot widen rulings.', 'Mutable source authors future law but cannot silently govern consumer.'], [], ['Complete accepted release, exact source-to-view relation/accessibility and any scope expansion authority.'], ['TRANSFORMATION_LIBRARY.faithful-projection'])
add(S,'constitutional-chain','definition_data','Interpreting the directional construction/repricing chain.',
    {'chain':['Goals','Intent','Product Definition','Requirements','Design','Realisation','Observations','Projection','Delta','Scenarios','Gap Analysis','Repricing / new Goals / Intent'], 'roles':{'Goals':'bounded current wave','Intent':'purpose/direction','Product Definition':'present current source WHAT/terms/end shape','Requirements':'invariant capabilities/constraints/governance/verification truth','Design':'structural HOW, interfaces/carriers/topology','ADRs':'durable design record, not superior layer','Realisation':'concrete tenant software/human/mixed process','Observations':'what occurred/currently exists at declared boundary','Projection':'source-checked question view','Delta':'intended/current drift','Scenarios':'operational meaning','Gap Analysis':'real-use insufficiency','Repricing':'owner-governed correction at affected layer'}},
    ['No unowned/ungrounded chain links; workspace persists as new A under current state/authority and admitted Z.', 'Context loss does not undo A; observation may invalidate belief/result but cannot change Z or confer permission.', 'WHAT bindings remain shared constitution; tenant HOW derivative until ratified; Product Definition differs from released Product/Install.'],
    ['Design selects any allowed realization; no unique implementation follows from premises.', 'Events are optional selected observation carrier; projection need not replay every event.', 'Design selects paths/mechanisms unless a path itself is constitutional.'], ['Current authoritative chain, selected outcome, work state and observed drift.'], ['FOUNDATIONS.workspace-and-context'])
add(S,'sprint-execution-boundary','constraint','Admitting/iterating/closing bounded sprint work under existing constitution.',
    'Sprint batches work and proof cost under cited authority without creating a new constitutional layer; it states wave, owners, scope/exclusions/classes, allowed debt, close trigger/law and paydown/repricing.',
    ['Deferral must remain local, visible, bounded and repayable; escrow is not acceptance and cannot discharge closure until paid, explicitly accepted by governing method or repriced.', 'Close reconciles evidence/work against authority, classifies gaps, accepts compliant work, opens paydown and escalates authority drift.', 'New Goal/Intent/Product/requirement/design/runtime/data/governance truth must split/escalate/reprice or take explicit lawful paydown; manifest alone cannot authorize landing.'],
    ['Recommend close at timebox, scope completion, excessive changed surface, unsafe uncertainty or inappropriate boundary.', 'Ticket Method owns mechanics; domain methods may allow cost optimization.'], ['Sprint boundary, governing authority, visible deferred debt, evidence and actual close treatment.'], ['TICKET_METHOD.sprint-close-review','TICKET_METHOD.sprint-compliance-escrow'])
